   require(Array.isArray(data.criteria), 'criteria')
   const ids = new Set()
   for (const criterion of data.criteria) {
     require(object(criterion) && identifier(criterion.id) && !ids.has(criterion.id), 'criterion id')
     ids.add(criterion.id)
